changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.gc_expire_quarantine_bounded( dim int, p_tenant_id text, p_quarantine_collection text, p_origin_collection text, p_cutoff text, p_floor_fraction float8, p_floor_min_chunks int, p_force boolean, p_row_limit int, p_count_refused boolean ) RETURNS TABLE(expired bigint, refused bigint, more boolean, floor_refused boolean) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_row_limit int; v_mine bigint; v_eligible bigint; v_protected bigint; v_refused bigint; v_probe bytea[]; v_victims bytea[]; v_deleted bytea[]; v_rows bigint := 0::bigint; v_more boolean := false; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_expire_quarantine_bounded: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- A non-positive bound is a caller error, not "unbounded": the point of this function is the bound. IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'gc_expire_quarantine_bounded: p_row_limit must be positive, got %. Use nexus.gc_expire_quarantine for the unbounded expiry.', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
-- 5,000 is gc_audit's chash ceiling (CatalogRepository.GC_AUDIT_MAX_CHASHES): a page never deletes more -- distinct chashes than its audit row can list. v_row_limit := LEAST(p_row_limit, 5000);
PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '25000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_quarantine_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'gc_expire_quarantine_bounded: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- another expiry page holds it, OR your own previous bounded call is still committing after the edge cut you. Poll pg_stat_activity for an active expiry on this collection before retrying; a fixed sleep builds a lock convoy.', p_tenant_id, p_quarantine_collection USING ERRCODE = 'lock_not_available'; END;
IF p_floor_fraction < 1 AND NOT COALESCE(p_force, false) THEN SELECT count(*), count(*) FILTER (WHERE s.past AND NOT s.referenced), count(*) FILTER (WHERE s.past AND s.referenced) INTO v_mine, v_eligible, v_protected FROM ( SELECT COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff AS past, EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash ) AS referenced FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE ) s;
IF v_eligible > 0 AND v_eligible >= p_floor_min_chunks AND v_eligible::float8 / v_mine::float8 > p_floor_fraction THEN -- Whole refusal: nothing deleted, no audit row; refused keeps the unbounded form's meaning. RETURN QUERY SELECT 0::bigint, v_eligible + v_protected, true, true; RETURN; END IF; v_refused := v_protected; ELSIF p_count_refused THEN SELECT count(*) INTO v_refused FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash ); END IF;
-- THE VICTIMS, selected from live state in chash order. The probe takes one past the page to answer `more`. -- The eligibility predicate is in the WHERE, ahead of the LIMIT. SELECT array_agg(x.chash ORDER BY x.chash) INTO v_probe FROM ( SELECT DISTINCT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash ) ORDER BY c.chash LIMIT v_row_limit + 1 ) x;
IF v_probe IS NULL THEN RETURN QUERY SELECT 0::bigint, v_refused, false, false; RETURN; END IF;
v_more := array_length(v_probe, 1) > v_row_limit; v_victims := CASE WHEN v_more THEN v_probe[1:v_row_limit] ELSE v_probe END;
-- Every eligibility predicate is restated: a row that changed and committed while this DELETE waited on its -- row lock is re-checked against its new version (READ COMMITTED), so it is not deleted if it no longer -- qualifies. What is reported and audited is what this DELETE really removed. WITH del AS ( DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_victims) AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash ) RETURNING c.chash ) SELECT count(*), array_agg(DISTINCT d.chash ORDER BY d.chash) INTO v_rows, v_deleted FROM del d;
-- One audit row per page that deleted anything, in the same transaction as the delete. At most 5,000 distinct -- chashes by the clamp, so the list is never truncated. IF v_rows > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_expire_quarantine_bounded', p_quarantine_collection, 'engine', false, array_length(v_deleted, 1), COALESCE( (SELECT jsonb_agg(encode(x, 'hex') ORDER BY x) FROM unnest(v_deleted) x), '[]'::jsonb), jsonb_build_object( 'origin_collection', p_origin_collection, 'cutoff', p_cutoff, 'row_limit', v_row_limit, 'rows', v_rows, 'more_after', v_more) || CASE WHEN v_refused IS NOT NULL THEN jsonb_build_object('refused', v_refused) ELSE '{}'::jsonb END ); END IF;
RETURN QUERY SELECT v_rows, v_refused, v_more, false; END; $$;
GRANT EXECUTE ON FUNCTION nexus.gc_expire_quarantine_bounded(int, text, text, text, text, float8, int, boolean, int, boolean) TO nexus_svc;
